import{_ as l,o as e,c as i,a2 as r}from"./chunks/framework.CAKCj7G0.js";const c=JSON.parse('{"title":"王迦南-运维开发工程师","description":"","frontmatter":{},"headers":[],"relativePath":"me/工作/简历.md","filePath":"me/工作/简历.md","lastUpdated":1768738899000}'),t={name:"me/工作/简历.md"};function o(p,a,n,s,h,d){return e(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="王迦南-运维开发工程师" tabindex="-1">王迦南-运维开发工程师 <a class="header-anchor" href="#王迦南-运维开发工程师" aria-label="Permalink to &quot;王迦南-运维开发工程师&quot;">​</a></h1><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><p>姓名：王迦南｜性别：男｜年龄：27岁｜联系电话：19138110250｜电子邮箱：1300182556@qq.com</p><p>工作经验：5年</p><h2 id="专业技能" tabindex="-1">专业技能 <a class="header-anchor" href="#专业技能" aria-label="Permalink to &quot;专业技能&quot;">​</a></h2><ul><li><p>编程语言：精通 Java、Golang，具备 OOP 及 DDD 思想</p></li><li><p>框架技术：精通 Spring、Gin 等服务框架，熟练使用 MyBatis、Gorm 等 ORM 框架</p></li><li><p>数据库：精通 MySQL、Redis 具备分库分表、索引优化等能力</p></li><li><p>架构能力：精通分布式/微服务架构，具备高并发、高可用系统设计与落地能力</p></li><li><p>运维开发：熟悉 Kubernetes、Docker，具备运维工具研发能力</p></li></ul><h2 id="核心优势" tabindex="-1">核心优势 <a class="header-anchor" href="#核心优势" aria-label="Permalink to &quot;核心优势&quot;">​</a></h2><ul><li><p>双栈架构与领域经验：5年实战经验，深耕金融/云计算领域，精通 Java、Golang 技术栈在保险履约、虚拟网络等场景落地，主导架构重构使业务稳定性显著提升</p></li><li><p>风险发现与保障能力：主导巡检方案提前修复30+风险点；支撑五福、行程码等国民级项目，保障系统可用性达99.99%</p></li><li><p>自动化提效专长：研发多款业务自动化机制，使机构入驻效率提升85.7%、人工流量覆盖效率提升3倍，减少50%重复开发工作</p></li></ul><h2 id="工作经历" tabindex="-1">工作经历 <a class="header-anchor" href="#工作经历" aria-label="Permalink to &quot;工作经历&quot;">​</a></h2><h3 id="数字马力-郑州-信息技术有限公司-开发工程师-2023-05-2025-05" tabindex="-1">数字马力(郑州)信息技术有限公司｜ 开发工程师｜2023.05 - 2025.05 <a class="header-anchor" href="#数字马力-郑州-信息技术有限公司-开发工程师-2023-05-2025-05" aria-label="Permalink to &quot;数字马力(郑州)信息技术有限公司｜ 开发工程师｜2023.05 - 2025.05&quot;">​</a></h3><p>核心职责：负责宠物保险履约核心模块的研发与稳定性保障，主导架构设计与模块拆分，支撑合作机构接入流程优化及业务多元化拓展落地</p><p><strong>关键业绩:</strong></p><ul><li><p>主导合作机构入驻体系升级：重构入驻流程与架构设计，优化审批链路，将机构入驻周期从14天缩短至2天，效率提升85.7%，半年内合作机构数量增长120%</p></li><li><p>落地业务配置通用方案：设计灵活的业务配置体系，支撑多险种、多服务场景快速适配，减少80%业务变更开发工作量，配置变更故障发生率下降60%</p></li></ul><h3 id="蚂蚁金服-杭州-网络技术有限公司-运维开发工程师-2021-08-2023-03" tabindex="-1">蚂蚁金服(杭州)网络技术有限公司｜运维开发工程师｜2021.08 - 2023.03 <a class="header-anchor" href="#蚂蚁金服-杭州-网络技术有限公司-运维开发工程师-2021-08-2023-03" aria-label="Permalink to &quot;蚂蚁金服(杭州)网络技术有限公司｜运维开发工程师｜2021.08 - 2023.03&quot;">​</a></h3><p>核心职责：负责支付宝全业务巡检平台搭建与迭代，主导重大活动技术保障方案制定，支撑支付、理财等核心业务场景的自动化巡检与压力测试落地</p><p><strong>关键业绩:</strong></p><ul><li><p>搭建高仿真压测体系：设计多元化业务流量模拟方案，为五福、消费券等大型活动提供核心压测支撑，保障活动期间系统零宕机，人工流量覆盖效率提升3倍</p></li><li><p>主导巡检平台技术创新：优化巡检脚本复用机制与平台架构，实现脚本多场景通用（巡检、压测、配置校验），复用率达70%；封装通用能力组件，减少同类型平台50%重复开发工作</p></li><li><p>关键项目保障落地：行程码、亚运一站通等重点项目</p></li></ul><h3 id="ucloud-虚拟网络研发工程师-2020-04-2021-07" tabindex="-1">UCloud｜虚拟网络研发工程师｜2020.04 - 2021.07 <a class="header-anchor" href="#ucloud-虚拟网络研发工程师-2020-04-2021-07" aria-label="Permalink to &quot;UCloud｜虚拟网络研发工程师｜2020.04 - 2021.07&quot;">​</a></h3><p>核心职责：负责 UCloud VPC 虚拟网络核心服务研发与迭代，主导控制面功能设计与优化，保障虚拟机网络通信、租户隔离、无损迁移等关键能力稳定运行</p><p><strong>关键业绩:</strong></p><ul><li><p>研发生产网络仿真环境：设计网络流表实时校验，将网络故障排查时间从2小时缩短至5分钟，故障修复效率提升91.7%</p></li><li><p>核心服务性能优化：优化控制面服务架构与数据访问策略，保障系统响应延迟稳定在100ms以内，接口成功率提升至99.99%</p></li><li><p>网络资源调度优化：设计网络资源预分配与动态调整机制，解决资源动态增容超时问题，资源分配成功率从85%提升至100%；保障主机无损迁移过程中网络通信零中断</p></li></ul><h2 id="教育经历" tabindex="-1">教育经历 <a class="header-anchor" href="#教育经历" aria-label="Permalink to &quot;教育经历&quot;">​</a></h2><p>山西大学｜软件工程｜本科｜2016.09 - 2020.06</p><p>**荣誉奖项：**蓝桥杯全国软件大赛三等奖、山西省高校团体编程竞赛第三名</p><p><strong>技能证书</strong> **：**计算机二/三级、中级软件设计师资格证</p>',25)])])}const m=l(t,[["render",o]]);export{c as __pageData,m as default};
